//! Concrete wire values generated by the gateway's compaction workflows.
//!
//! Only producer-owned fragments retain arbitrary JSON; generated controls, checkpoints,
//! and usage reports keep their concrete types until the HTTP/SSE serialization boundary.

use crate::ir::IrUsage;
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// A completed checkpoint rendered before an answer or as a compact-only result.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
pub(crate) enum Checkpoint {
    /// A gateway-generated Responses carrier.
    Responses(ResponsesCheckpoint),
    /// A gateway-generated Messages carrier.
    Messages(MessagesCheckpoint),
    /// Complete producer-owned state or a native canonical window item, preserved verbatim.
    Native(Value),
}

impl From<Value> for Checkpoint {
    fn from(value: Value) -> Self {
        Self::Native(value)
    }
}

/// The gateway-generated Responses compaction item.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", rename = "compaction", deny_unknown_fields)]
pub(crate) struct ResponsesCheckpoint {
    /// Gateway-issued item identifier.
    pub(crate) id: String,
    /// Authenticated gateway state carrier.
    pub(crate) encrypted_content: String,
    /// Optional authoring provenance.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) created_by: Option<String>,
}

/// The gateway-generated Messages compaction block.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "type", rename = "compaction", deny_unknown_fields)]
pub(crate) struct MessagesCheckpoint {
    /// Readable summary or the fixed encrypted-state transport description.
    pub(crate) content: String,
    /// Authenticated gateway carrier bound to the visible content.
    pub(crate) signature: String,
}

/// One iteration report rendered in the Messages usage array.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(untagged)]
pub(crate) enum UsageIteration {
    /// A gateway-generated report with fully known fields.
    Gateway(IterationReport),
    /// An authoritative producer report, including all vendor extensions.
    Native(Value),
}

impl<'de> Deserialize<'de> for UsageIteration {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        Value::deserialize(deserializer).map(Self::Native)
    }
}

impl From<Value> for UsageIteration {
    fn from(value: Value) -> Self {
        Self::Native(value)
    }
}

/// The kind of billed sampling iteration.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum SamplingKind {
    /// Work producing a compaction checkpoint.
    Compaction,
    /// Work producing the caller's ordinary answer.
    Message,
}

/// Usage generated from one actual dispatch in the gateway ledger.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct IterationReport {
    /// Sampling operation kind.
    #[serde(rename = "type")]
    pub(crate) kind: SamplingKind,
    /// Tokens consumed by the input.
    pub(crate) input_tokens: u64,
    /// Tokens produced by the output.
    pub(crate) output_tokens: u64,
    /// Input tokens written to the upstream cache, when reported.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) cache_creation_input_tokens: Option<u64>,
    /// Input tokens served from the upstream cache, when reported.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) cache_read_input_tokens: Option<u64>,
}

impl UsageIteration {
    /// Renders actual observed usage without inventing absent breakdowns.
    pub(crate) const fn gateway(kind: SamplingKind, usage: IrUsage) -> Self {
        Self::Gateway(IterationReport {
            kind,
            input_tokens: usage.input_tokens,
            output_tokens: usage.output_tokens,
            cache_creation_input_tokens: usage.cache_write_tokens,
            cache_read_input_tokens: usage.cached_tokens,
        })
    }
}

/// One Responses automatic-compaction control passed to a native producer.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename = "compaction")]
pub(crate) struct AutomaticEntry {
    /// Caller-supplied threshold; absence keeps the producer's default.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub(crate) compact_threshold: Option<u64>,
}

impl From<&super::compaction_control::AutomaticEntry> for AutomaticEntry {
    fn from(entry: &super::compaction_control::AutomaticEntry) -> Self {
        Self {
            compact_threshold: entry.compact_threshold,
        }
    }
}

/// One Messages native threshold edit.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename = "compact_20260112")]
pub(crate) struct ThresholdEdit {
    /// Caller-supplied input-token trigger.
    #[serde(skip_serializing_if = "Option::is_none")]
    trigger: Option<InputTokenTrigger>,
    /// Present only when the caller requested a pause.
    #[serde(
        skip_serializing_if = "Option::is_none",
        rename = "pause_after_compaction"
    )]
    should_pause_after_compaction: Option<bool>,
    /// Caller-supplied summarization instructions.
    #[serde(skip_serializing_if = "Option::is_none")]
    instructions: Option<String>,
}

/// Input-token trigger carried by a Messages threshold edit.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename = "input_tokens")]
struct InputTokenTrigger {
    /// Exact caller-supplied threshold.
    value: u64,
}

impl From<&super::compaction_control::ThresholdEdit> for ThresholdEdit {
    fn from(edit: &super::compaction_control::ThresholdEdit) -> Self {
        Self {
            trigger: edit.trigger.map(|value| InputTokenTrigger { value }),
            should_pause_after_compaction: edit.pause_after_compaction.then_some(true),
            instructions: edit.instructions.clone(),
        }
    }
}
